      {
        "name": "orientation",
        "type": "'horizontal' | 'vertical'",
        "description": "Orientation of the divider.",
        "default": "'horizontal'"
      },
      {
        "name": "label",
        "type": "ReactNode",
        "description": "Optional label centered on the divider. Numeric zero is preserved; null, booleans, and empty strings render no label."
      },
      {
        "name": "variant",
        "type": "'subtle' | 'strong'",
        "description": "Visual weight of the divider line.",
        "default": "'subtle'"
      },
      {
        "name": "isFullBleed",
        "type": "boolean",
        "description": "Extend the divider to container edges with negative margins.",
        "default": "false"
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-divider",
          "visualProps": [
            "orientation",
            "variant"
          ]
        }
      ]
    },
    "usage": {
      "anatomy": [
        {
          "name": "Divider group",
          "required": true,
          "description": "Separator group that arranges one or two rules around an optional label."
        },
        {
          "name": "Rule",
          "required": true,
          "description": "Painted line segment; a second segment renders when a label is present."
        },
        {
          "name": "Label",
          "required": false,
          "description": "Optional content displayed between two rule segments."
        }
      ],
      "description": "A visual separator that divides content into distinct sections. Use to create clear boundaries between groups of related content, or to demarcate interactive regions within a layout.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use subtle dividers between related content sections and strong dividers for high-contrast boundaries."
        },
        {
          "guidance": true,
          "description": "Add a label to the divider when sections need a visible category heading."
        },
        {
          "guidance": false,
          "description": "Overuse dividers; rely on spacing and layout to separate content when possible."
        }
      ]
    },
